using System.Collections.Generic;using UnityEngine;using UnityEngine.InputSystem;
public class CheckoutStation:MonoBehaviour{
 [SerializeField] private CheckoutManager checkoutManager;[SerializeField,Min(1f)]private float lookDistance=4f;[SerializeField]private Color aimedColor=new Color(.25f,1f,.35f,1f);
 private PlayerMovement player;private Camera playerCamera;private bool highlighted;private Renderer[] renderers;private MaterialPropertyBlock block;private readonly Dictionary<Renderer,Color> originalColors=new Dictionary<Renderer,Color>();
 void Awake(){if(!checkoutManager)checkoutManager=CheckoutManager.Instance;renderers=GetComponentsInChildren<Renderer>(true);block=new MaterialPropertyBlock();CacheColors();}
 void Start(){player=FindFirstObjectByType<PlayerMovement>();ResolveCamera();if(!checkoutManager)checkoutManager=CheckoutManager.Instance;}
 void Update(){if(!checkoutManager)checkoutManager=CheckoutManager.Instance;if(checkoutManager!=null&&checkoutManager.IsActive){SetHighlight(false);return;}bool aimed=IsAimed();SetHighlight(aimed);if(aimed&&Keyboard.current!=null&&Keyboard.current.eKey.wasPressedThisFrame){if(checkoutManager)checkoutManager.EnterCheckout();else Debug.LogError("CheckoutManager missing in scene.",this);}}
 void ResolveCamera(){if(player==null)player=FindFirstObjectByType<PlayerMovement>();if(player!=null&&player.playerCamera!=null)playerCamera=player.playerCamera.GetComponent<Camera>();}
 bool IsAimed(){if(playerCamera==null)ResolveCamera();if(playerCamera==null)return false;Ray ray=new Ray(playerCamera.transform.position,playerCamera.transform.forward);if(!Physics.Raycast(ray,out RaycastHit hit,lookDistance,Physics.DefaultRaycastLayers,QueryTriggerInteraction.Collide))return false;return hit.collider.GetComponentInParent<CheckoutStation>()==this;}
 void CacheColors(){foreach(Renderer r in renderers){if(!r)continue;foreach(Material m in r.sharedMaterials){if(!m)continue;if(m.HasProperty("_BaseColor")){originalColors[r]=m.GetColor("_BaseColor");break;}if(m.HasProperty("_Color")){originalColors[r]=m.GetColor("_Color");break;}}}}
 void SetHighlight(bool state){if(highlighted==state||renderers==null)return;highlighted=state;foreach(Renderer r in renderers){if(!r)continue;r.GetPropertyBlock(block);Color c=state?aimedColor:(originalColors.TryGetValue(r,out Color orig)?orig:Color.white);block.SetColor("_BaseColor",c);block.SetColor("_Color",c);block.SetColor("_EmissionColor",state?aimedColor*1.2f:Color.black);r.SetPropertyBlock(block);}}
 void OnDisable(){SetHighlight(false);}
}